with incoming(lemma, kind, sense_id, ordinal, pos, gender, text, example, example_translation) as (values ('komme over', 'phrase', 'a4cf9f7c-42bd-58d8-9451-cfddc677d2a5', 1, 'verb', null, 'приходити (в гості)', 'Vil du komme over til mig i aften?', 'Ти прийдеш до мене сьогодні ввечері?'), ('komme over', 'phrase', 'd4a372bb-97b6-5da7-b937-3fe9bafad910', 2, 'verb', null, 'долати (труднощі)', 'Hun kom over sin frygt for hunde.', 'Вона подолала страх перед собаками.'), ('gå under', 'phrase', 'c4d82663-1ab7-53c8-9231-1da8b7f06319', 1, 'verb', null, 'тонути (про корабель)', 'Det gamle skib gik under i stormen.', 'Старий корабель затонув у бурі.'), ('gå under', 'phrase', 'a8de78fc-f7ea-57fa-95de-a648a293ce36', 2, 'verb', null, 'гинути (про цивілізацію, компанію)', 'Mange små butikker går under i krisen.', 'Багато малих магазинів розоряються під час кризи.'), ('dele sig', 'phrase', '84f2c3e9-b949-56c2-a8a4-47c6eab03672', 1, 'verb', null, 'розділятися (на частини)', 'Floden deler sig i to grene lige efter broen.', 'Річка розгалужується на дві гілки одразу після мосту.'), ('dele sig', 'phrase', '347ad1c2-eb0d-56e8-9ece-00e1b6b4aa02', 2, 'verb', null, 'розходитися (про дорогу, групу)', 'Stien deler sig, så vi må vælge en vej.', 'Стежка розгалужується, тож нам треба обрати шлях.'), ('holde for', 'phrase', '12f65054-ad15-5e09-821b-c605b6e2c51e', 1, 'verb', null, 'закривати рукою (ніс, вуха, очі)', 'Jeg holder for ørerne, når toget kører forbi.', 'Я закриваю вуха, коли проїжджає потяг.'), ('ligge over', 'phrase', '117cab92-b318-59fc-8933-5df8fbcb1f0f', 1, 'verb', null, 'залишатися на ніч', 'Jeg ligger over hos min veninde i weekenden.', 'Я залишаюся у подруги на вихідних.'), ('blive tilbage', 'phrase', '1666bbdb-5e91-5cf0-b3d7-233ff2a4671b', 1, 'verb', null, 'залишатися (не йти)', 'Hun bliver tilbage på kontoret, når de andre går hjem.', 'Вона залишається в офісі, коли інші йдуть додому.'), ('holde sig tilbage', 'phrase', '7634fcde-aed3-52f7-9875-08894384223f', 1, 'verb', null, 'стримуватися', 'Jeg holdt mig tilbage, selvom jeg var vred.', 'Я стримувався, хоч і був злий.'), ('spille med', 'phrase', '2cebd4f5-4d3d-517a-91b3-ce99a556fa4e', 1, 'verb', null, 'підігравати (погоджуватися з чиїмось планом)', 'Han spiller med på ideen om en tur til stranden.', 'Він підіграє ідеї поїздки на пляж.'), ('køre ind i', 'phrase', '14cdea87-6993-5bae-bfcc-0f2347d38fa9', 1, 'verb', null, 'врізатися (у щось)', 'Bilen kørte ind i et træ.', 'Автомобіль врізався в дерево.'), ('slå i', 'phrase', 'b7218141-5770-5700-b5dc-d9e363b310fe', 1, 'verb', null, 'вдаряти (по чомусь)', 'Han slog i bordet af vrede.', 'Він вдарив по столу від злості.'), ('slå sig på', 'phrase', 'fbec78cc-0dd0-5109-9066-79b1190f2d3e', 1, 'verb', null, 'забити (собі)', 'Jeg slog mig på knæet, da jeg faldt.', 'Я забив коліно, коли впав.'), ('møde op', 'phrase', '35400702-7646-55ff-acf5-bbd02edc8fd0', 1, 'verb', null, 'з''являтися (кудись)', 'Hun mødte op til mødet uden sin computer.', 'Вона прийшла на зустріч без комп''ютера.'), ('handle med', 'phrase', '77588a85-6ece-52f0-b6ec-3531f5694fdc', 1, 'verb', null, 'торгувати (чимось)', 'De handler med frugt og grøntsager på torvet.', 'Вони торгують фруктами та овочами на площі.'), ('stige af', 'phrase', '52dfa294-4641-596f-9289-b508481e2821', 1, 'verb', null, 'виходити (з транспорту)', 'Jeg stiger af bussen ved stationen.', 'Я виходжу з автобуса на станції.'), ('have lov til', 'phrase', '9dec08c9-ed2a-527e-b710-49139b15706a', 1, 'verb', null, 'мати дозвіл', 'Børnene har lov til at lege i haven.', 'Дітям дозволено гратися в саду.'), ('vente med', 'phrase', 'ed35c79d-4e8f-57c7-bf5c-9c4ffbcd4240', 1, 'verb', null, 'відкладати (щось)', 'Vi venter med mødet til i morgen.', 'Ми відкладаємо нараду до завтра.'), ('stille op', 'phrase', '6c73dcf5-be9f-5a51-87c4-0a819a3eda80', 1, 'verb', null, 'висувати свою кандидатуру (на виборах)', 'Hun stiller op til kommunalvalget næste år.', 'Наступного року вона балотується на муніципальних виборах.'), ('stille op', 'phrase', 'b410c00e-c092-5787-be25-d7f765f5919b', 2, 'verb', null, 'вишиковувати(ся) в ряд', 'Læreren bad børnene stille op på to rækker.', 'Вчитель попросив дітей вишикуватися у два ряди.'), ('bag ved', 'phrase', 'b9296121-df4e-5c6c-8e0d-c74e1a2a2f47', 1, 'preposition', null, 'позаду', 'Huset ligger lige bag ved skolen.', 'Будинок розташований прямо за школою.'), ('hjælpe på', 'phrase', 'b87e8502-a18a-531b-bf0a-e9840f9ba42d', 1, 'verb', null, 'покращувати (ситуацію)', 'Det hjælper på humøret at gå en tur.', 'Прогулянка покращує настрій.'), ('flytte sig', 'phrase', 'bd7988d3-059a-567c-8f6c-46429e9938a8', 1, 'verb', null, 'рухатися, переміщатися', 'Kan du flytte dig lidt til siden?', 'Можеш трохи відсунутися вбік?'), ('flytte ud', 'phrase', '09fbbe18-ca96-53eb-963d-25e5bd9cf413', 1, 'verb', null, 'виїжджати (з квартири)', 'Min nabo flyttede ud i sidste uge.', 'Мій сусід виїхав минулого тижня.'), ('rette på', 'phrase', '3a5829c2-8b70-5940-bdeb-10a8f8162728', 1, 'verb', null, 'поправляти (одяг, зачіску)', 'Hun retter på slipset før mødet.', 'Вона поправляє краватку перед зустріччю.'), ('blive væk', 'phrase', '42e42e7f-ca94-508e-8429-fa2cd9751137', 1, 'verb', null, 'пропадати, губитися', 'Min nøgle bliver væk hele tiden.', 'Мій ключ постійно губиться.'), ('være igennem', 'phrase', '6bd6fd58-3452-5d68-84a0-9c505008cc62', 1, 'verb', null, 'пройти через (щось)', 'Hun er igennem en svær periode lige nu.', 'Зараз вона переживає складний період.'), ('lave numre', 'phrase', '8bd4fd3f-3bfe-5655-8307-ed2407b153ee', 1, 'verb', null, 'витворяти, влаштовувати сцени', 'Børnene laver numre, når de er trætte.', 'Діти влаштовують сцени, коли втомлені.'), ('hen ad', 'phrase', '74f8f698-59de-5fca-b651-bc3eb491e09b', 1, 'preposition', null, 'уздовж, у напрямку до', 'De gik hen ad vejen i stilhed.', 'Вони йшли дорогою мовчки.'), ('løbe af med', 'phrase', 'a4b72c87-82c8-5998-a035-32266643a379', 1, 'verb', null, 'утікати з (чимось)', 'Tyven løb af med min taske.', 'Злодій утік з моєю сумкою.'), ('løbe af med', 'phrase', 'ac66a13b-caac-592f-b1df-2059f22c3cc3', 2, 'verb', null, 'вигравати (легко)', 'Hun løb af med førstepræmien.', 'Вона легко виграла першу премію.'), ('håbe på', 'phrase', '8208e60d-67f3-5933-8a77-3c2cbf11eb05', 1, 'verb', null, 'сподіватися на', 'Jeg håber på godt vejr i morgen.', 'Сподіваюся, завтра буде гарна погода.'), ('tage en beslutning', 'phrase', '672dc7a2-2e01-58ae-a05f-ce9350745dbd', 1, 'verb', null, 'приймати рішення', 'Hun tager en beslutning om sit nye job i morgen.', 'Вона прийме рішення щодо своєї нової роботи завтра.'), ('komme i tvivl', 'phrase', '73f6b0eb-d1ef-5a50-8a75-0b6ad5986a95', 1, 'verb', null, 'засумніватися', 'Jeg kom i tvivl om svaret var rigtigt.', 'Я засумнівався, чи правильна відповідь.'), ('være foran', 'phrase', '4327e985-37a7-5817-962a-2267eed915ae', 1, 'verb', null, 'бути попереду', 'Vores hold er foran med to mål.', 'Наша команда веде на два голи.'), ('stemme i', 'phrase', '48cebe76-437d-5f81-a0ec-d59d532b9b04', 1, 'verb', null, 'підспівувати', 'Alle børnene stemte i på omkvædet.', 'Усі діти підспівували приспів.'), ('skifte til', 'phrase', '8a0a1b49-cebe-5c51-8526-0be78de2cfb1', 1, 'verb', null, 'перемикатися на (щось)', 'Jeg skifter til en anden kanal.', 'Я перемикаюся на інший канал.'), ('sidde inde', 'phrase', '8cbebd22-a90a-57e2-943d-a76e6aebc1a1', 1, 'verb', null, 'сидіти у в''язниці', 'Han sad inde i to år for tyveri.', 'Він був ув''язнений на два роки за крадіжку.'), ('sidde inde', 'phrase', 'df3dc8dc-99a7-52f7-970e-85a50a18d1f0', 2, 'verb', null, 'володіти (знаннями)', 'Hun sidder inde med vigtig viden om sagen.', 'Вона має важливі відомості про цю справу.'), ('stå inde for', 'phrase', '315e5f1f-c533-5783-bde3-a0817f8b59fe', 1, 'verb', null, 'ручатися (за якість, надійність)', 'Jeg står inde for kvaliteten af vores produkter.', 'Я ручаюся за якість наших продуктів.'), ('være inde', 'phrase', 'c5c834a5-8b15-5902-9031-5afe70414d06', 1, 'verb', null, 'бути всередині (у приміщенні)', 'Jeg er inde i stuen og læser en bog.', 'Я у вітальні, читаю книгу.'), ('melde sig til', 'phrase', 'e9e9eadd-32a3-59ab-ba84-cd6f8934f5f0', 1, 'verb', null, 'записуватися (на курс, захід)', 'Jeg melder mig til et kursus i næste uge.', 'Наступного тижня я записуюся на курс.'), ('gå fra borde', 'phrase', '2b6c0860-9b26-5e05-840b-02e36eaa1e3f', 1, 'verb', null, 'сходити на берег (з судна)', 'Passagererne gik fra borde i København.', 'Пасажири висадилися в Копенгагені.'), ('slippe af med', 'phrase', '7cb01bcd-f057-53dd-96c3-2684ae8a3f82', 1, 'verb', null, 'позбуватися', 'Jeg slap af med min gamle sofa i går.', 'Вчора я позбувся старого дивана.'), ('synge med', 'phrase', '0d9c0305-ee61-58bd-ad3f-076d9bfd9627', 1, 'verb', null, 'підспівувати', 'Hun synger med på sangen i radioen.', 'Вона підспівує пісні по радіо.'), ('tanke op', 'phrase', '8088c4e1-7e8e-53a5-b693-43ecb38e6f1b', 1, 'verb', null, 'заправлятися (пальним)', 'Vi tanker op inden den lange tur.', 'Ми заправляємося перед довгою поїздкою.'), ('skære sig', 'phrase', '75b4479a-c452-5380-983a-c5157dd9a24b', 1, 'verb', null, 'порізатися', 'Jeg skar mig på kniven i går.', 'Вчора я порізався ножем.'), ('skifte emne', 'phrase', '4f771aed-2bd0-5f70-9f44-5d9751138041', 1, 'verb', null, 'змінювати тему', 'Vi skifter emne, fordi det er for pinligt.', 'Ми змінюємо тему, бо це надто соромно.'), ('styre sig', 'phrase', '70f12b32-bd63-5cd0-a503-ceeefb9c2e65', 1, 'verb', null, 'стримуватися', 'Du må styre dig, selvom du er vred.', 'Ти маєш контролювати себе, навіть якщо злишся.'), ('snakke sammen', 'phrase', '6dff755f-b23f-5fc6-8d15-9a3997f15d44', 1, 'verb', null, 'розмовляти (один з одним)', 'Vi snakker sammen hver aften.', 'Ми розмовляємо щовечора.'), ('fejre jul', 'phrase', 'd9479a0d-2258-5e06-891a-6c87be1c0d55', 1, 'verb', null, 'святкувати Різдво', 'Vi fejrer jul hos mine forældre i år.', 'Цього року ми святкуємо Різдво у моїх батьків.'), ('fred og ro', 'phrase', '19ea8ca8-f400-5104-9c4c-03b593245d7d', 1, 'phrase', null, 'тиша і спокій', 'Jeg har brug for fred og ro efter arbejde.', 'Мені потрібен спокій і тиша після роботи.'), ('tage på ferie', 'phrase', '82d4fb2c-ef98-5bef-9735-d78a132dfc0b', 1, 'verb', null, 'їхати у відпустку (в подорож)', 'Vi tager på ferie til Italien hver sommer.', 'Щоліта ми їдемо у відпустку до Італії.'), ('springe ind', 'phrase', '18371915-8d67-5cb4-90fb-c876602d6205', 1, 'verb', null, 'підміняти (когось, тимчасово)', 'Hun sprang ind for den syge lærer i går.', 'Вчора вона підмінила хвору вчительку.'), ('finde sig i', 'phrase', '9e2de5e6-2850-5349-9138-81c5f07ba07f', 1, 'verb', null, 'миритися з (чимось), терпіти', 'Hun finder sig i meget fra sin chef.', 'Вона багато чого терпить від свого начальника.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'uk'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'uk', text, pos, gender, example, example_translation, 'pipeline-phrases-0007' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
